function parseArray(src) {
  var parts = String(src).split(',').map(function (s) { return Number(s.trim()); });
  if (parts.length !== 6 || parts.some(function (v) { return !isFinite(v); })) {
    throw new Error('Enter exactly six comma-separated numbers.');
  }
  return parts;
}

function workerSource(userCode, initial) {
  return `
    const INIT = ${JSON.stringify(initial)};
    const USER = ${JSON.stringify(userCode)};
    let A = INIT.slice();
    let frames = [];
    let opCount = 0;
    const OP_CAP = 4000, FRAME_CAP = 1200;
    let prefixLen = 1, keyIndex = null, currentJ = null;
    let passResults = [];
    function copyState(extra) {
      const base = { A: A.slice(), prefixLen, keyIndex, currentJ };
      if (extra) for (const k in extra) base[k] = extra[k];
      return base;
    }
    function sortedPrefix(k) {
      for (let i = 1; i < k; i++) if (A[i-1] > A[i]) return false;
      return true;
    }
    function append(kind, indices, message, extra) {
      opCount++;
      if (opCount > OP_CAP) throw new Error('Operation cap reached; possible infinite loop.');
      if (frames.length >= FRAME_CAP) throw new Error('Frame cap reached; replay is too long.');
      frames.push({ kind, state: copyState(extra), indices: indices || [], message: message || '' });
    }
    function idx(i) {
      if (!Number.isInteger(i) || i < 1 || i > A.length) throw new Error('Index ' + i + ' is outside 1..' + A.length + '.');
    }
    self.len = function () { append('len', [], 'len() → ' + A.length); return A.length; };
    self.startPass = function (j) {
      idx(j);
      if (j < 2) throw new Error('startPass(j) expects j ≥ 2.');
      currentJ = j; keyIndex = j; prefixLen = j - 1;
      append('startPass', [j], 'startPass(' + j + '): A[' + j + ']=' + A[j-1] + ' is the key.');
    };
    self.compare = function (i, j) {
      idx(i); idx(j);
      const ans = A[i-1] > A[j-1];
      append('compare', [i, j], 'compare A[' + i + ']=' + A[i-1] + ' with A[' + j + ']=' + A[j-1] + ' → ' + ans);
      return ans;
    };
    self.shift = function (i) {
      idx(i);
      if (i === 1) throw new Error('shift(1) cannot move left.');
      const before = A.slice();
      const t = A[i-1]; A[i-1] = A[i-2]; A[i-2] = t;
      if (keyIndex === i) keyIndex = i - 1;
      else if (keyIndex === i - 1) keyIndex = i;
      append('shift', [i-1, i], 'shift(' + i + '): swap ' + before[i-2] + ' and ' + before[i-1] + '.', { shiftFrom: i, shiftTo: i - 1 });
    };
    self.finishPass = function () {
      if (currentJ == null) throw new Error('finishPass() called before startPass(j).');
      prefixLen = currentJ;
      const ok = sortedPrefix(prefixLen);
      passResults.push({ j: currentJ, ok });
      keyIndex = null;
      append('finishPass', [], 'finishPass(): prefix A[1..' + prefixLen + '] is ' + (ok ? 'sorted.' : 'not sorted.'), { passOk: ok });
    };
    self.note = function (text) { append('note', [], String(text)); };
    const api = Object.freeze({ len:self.len, startPass:self.startPass, compare:self.compare, shift:self.shift, finishPass:self.finishPass, note:self.note });
    append('initial', [], 'Initial array: [' + A.join(', ') + ']');
    try {
      (0, eval)(USER);
      if (typeof insertionSort !== 'function') throw new Error('Define function insertionSort().');
      insertionSort();
      append('done', [], 'Program finished.');
      self.postMessage({ type:'done', frames, final:A.slice(), passResults });
    } catch (e) {
      if (frames.length >= FRAME_CAP) frames = frames.slice(0, FRAME_CAP - 1);
      frames.push({ kind:'error', state: copyState({ error:true }), indices:[], message:'Error: ' + (e && e.message ? e.message : e) });
      self.postMessage({ type:'error', frames, error:(e && e.message ? e.message : String(e)), final:A.slice(), passResults });
    }
  `;
}

function runStudentCode() {
  stopPlay();
  var code = document.getElementById('editInsertionSortCode').value;
  var arr;
  try { arr = parseArray(document.getElementById('editInsertionSortInput').value); }
  catch (e) { setStatus('error', e.message); return; }

  document.getElementById('runBtn').disabled = true;
  setStatus('running', 'Status: running');
  document.getElementById('runLog').textContent = '';

  if (worker) worker.terminate();
  var blob = new Blob([workerSource(code, arr)], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  worker = new Worker(url);
  var timedOut = false;
  var timer = setTimeout(function () {
    timedOut = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = [{ kind: 'error', state: { A: arr, prefixLen: 1, keyIndex: null, error: true }, indices: [], message: 'Error: timed out; possible infinite loop.' }];
    frameIndex = 0;
    drawReplay(frames[0]);
    setStatus('error', 'Status: error — timed out');
    document.getElementById('runBtn').disabled = false;
  }, 1800);

  worker.onmessage = function (ev) {
    if (timedOut) return;
    clearTimeout(timer);
    URL.revokeObjectURL(url);
    frames = ev.data.frames || [];
    frameIndex = 0;
    var verdict = checkVerdict(ev.data.final, ev.data.passResults, frames);
    if (frames.length) drawReplay(frames[0]);
    setStatus(verdict.ok ? 'correct' : (ev.data.type === 'error' ? 'error' : 'wrong'), verdict.message);
    updatePlaybackUi();
    document.getElementById('runBtn').disabled = false;
  };
  worker.onerror = function (e) {
    clearTimeout(timer);
    URL.revokeObjectURL(url);
    frames = [{ kind: 'error', state: { A: arr, prefixLen: 1, keyIndex: null, error: true }, indices: [], message: 'Error: ' + e.message }];
    frameIndex = 0;
    drawReplay(frames[0]);
    setStatus('error', 'Status: error — ' + e.message);
    document.getElementById('runBtn').disabled = false;
  };
}

function checkVerdict(finalArr, passResults, frs) {
  var bad = [];
  for (var i = 1; i < finalArr.length; i++) if (finalArr[i - 1] > finalArr[i]) bad.push(i, i + 1);
  var allPasses = passResults && passResults.length === finalArr.length - 1 &&
    passResults.every(function (p) { return p.ok; });
  var hasError = frs.some(function (f) { return f.kind === 'error'; });
  if (hasError) return { ok: false, message: 'Status: error — see final replay frame.' };
  if (bad.length === 0 && allPasses) return { ok: true, message: 'Status: correct — final array is sorted and every pass left a sorted prefix.' };
  if (frs.length) frs[frs.length - 1].state.bad = bad;
  return { ok: false, message: 'Status: wrong answer — the final array or a pass prefix is not sorted.' };
}

function setStatus(kind, msg) {
  var el = document.getElementById('runStatus');
  el.textContent = msg;
  el.style.color = kind === 'correct' ? '#087b24' : (kind === 'error' || kind === 'wrong' ? '#b00020' : '#555');
}

function drawReplay(frame) {
  staticMode = false;
  draw.clear();
  draw.viewbox(0, 0, 900, 580);
  var g = draw.group();
  var A = frame.state.A || [];
  var x = 170, y = 185, cw = 90, ch = 90;
  addText(g, 'Replay frame', 450, 48, 34, '#000');
  for (var i = 0; i < 6; i++) addText(g, i + 1, x + i * cw + cw / 2, y - 28, 42, '#000');
  for (var c = 0; c < 6; c++) {
    var idx = c + 1, fill = '#fff', txt = '#000';
    if (frame.state.prefixLen && idx <= frame.state.prefixLen) fill = '#cfcfcf';
    if (frame.state.keyIndex === idx) { fill = '#000'; txt = '#fff'; }
    if (frame.kind === 'done' && !frame.state.bad) fill = '#fff';
    g.rect(cw, ch).move(x + c * cw, y).fill(fill).stroke({ color: '#000', width: 2.5 });
    addText(g, A[c], x + c * cw + cw / 2, y + ch / 2, 55, txt);
  }
  if (frame.indices) {
    frame.indices.forEach(function (n) {
      g.rect(cw - 8, ch - 8).move(x + (n - 1) * cw + 4, y + 4)
        .fill('none').stroke({ color: '#5a8fd8', width: 5 });
    });
  }
  if (frame.state.bad) {
    frame.state.bad.forEach(function (n) {
      g.rect(cw - 12, ch - 12).move(x + (n - 1) * cw + 6, y + 6)
        .fill('none').stroke({ color: '#b00020', width: 5, dasharray: '8,5' });
    });
  }
  var mk = makeMarkers();
  if (frame.kind === 'shift' && frame.state.shiftFrom) {
    drawArrow(g, x + (frame.state.shiftFrom - 0.5) * cw, x + (frame.state.shiftTo - 0.5) * cw, y, '#000', mk.black, 180, 2.6);
    drawArrow(g, x + (frame.state.shiftTo - 0.5) * cw, x + (frame.state.shiftFrom - 0.5) * cw, y, '#8b8b8b', mk.gray, 145, 2.1);
  }
  if (frame.kind === 'compare') {
    addText(g, 'comparison', 450, 335, 28, '#000');
  }
  if (frame.state.error) addText(g, '!', 450, 365, 70, '#b00020', 'bold');
  updatePlaybackUi();
}

function updatePlaybackUi() {
  document.getElementById('frameCounter').textContent = frames.length ? ((frameIndex + 1) + ' of ' + frames.length) : 'not run';
  var f = frames[frameIndex];
  document.getElementById('frameCaption').textContent = f ? f.message : '';
  if (frames.length) {
    var start = Math.max(0, frameIndex - 10);
    document.getElementById('runLog').textContent = frames.slice(start, frameIndex + 1)
      .map(function (fr, k) { return (start + k + 1) + '. ' + fr.message; }).join('\n');
  }
}
function firstFrame() { if (!frames.length) return; frameIndex = 0; drawReplay(frames[frameIndex]); }
function prevFrame() { if (!frames.length) return; frameIndex = Math.max(0, frameIndex - 1); drawReplay(frames[frameIndex]); }
function nextFrame() { if (!frames.length) return; frameIndex = Math.min(frames.length - 1, frameIndex + 1); drawReplay(frames[frameIndex]); if (frameIndex === frames.length - 1) stopPlay(); }
function togglePlay() {
  if (!frames.length) return;
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playBtn').textContent = 'Pause';
  playTimer = setInterval(function () {
    if (frameIndex >= frames.length - 1) stopPlay();
    else nextFrame();
  }, 650 / Number(document.getElementById('speedInput').value || 1));
}
function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = 'Play';
}

